 @Override protected void onStart(){super.onStart();configureWindow(false);surface.setAlpha(0);surface.setScaleX(.9f);surface.setScaleY(.9f);surface.animate().alpha(1).scaleX(1).scaleY(1).setDuration(300).start();body.post(()->{tabs[section].requestFocus();revealTab(section);});load(false);ui.postDelayed(daily,60000);}
 private void configureWindow(boolean fullscreen){Window w=getWindow();if(w==null)return;w.setBackgroundDrawableResource(android.R.color.transparent);w.clearFlags(WindowManager.LayoutParams.FLAG_DIM_BEHIND);w.addFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);w.setWindowAnimations(0);w.getDecorView().setSystemUiVisibility(host.getWindow().getDecorView().getSystemUiVisibility());w.setGravity(fullscreen?Gravity.TOP|Gravity.LEFT:Gravity.TOP|Gravity.RIGHT);w.setLayout(fullscreen?host.screenW:x(2400),fullscreen?host.screenH:y(1050));WindowManager.LayoutParams a=w.getAttributes();a.x=fullscreen?0:Math.round(host.screenW*.028f);a.y=fullscreen?0:Math.round(host.screenH*.16f);w.setAttributes(a);w.setSoftInputMode(WindowManager.LayoutParams.SOFT_INPUT_ADJUST_NOTHING);}
 private void normalVideo(){if(videoPane.getParent() instanceof android.view.ViewGroup)((android.view.ViewGroup)videoPane.getParent()).removeView(videoPane);put(body,videoPane,800,270,1560,550);}
 void setFull(boolean value){if(full==value||closing||panel!=null)return;full=value;if(full){beforeFull=getCurrentFocus();body.setVisibility(View.GONE);((ViewGroup)videoPane.getParent()).removeView(videoPane);surface.addView(videoPane,new FrameLayout.LayoutParams(-1,-1));surface.setClipToOutline(false);configureWindow(true);fullscreen.setText("⛶ رجوع للنافذة");showControls();play.requestFocus();}else{ui.removeCallbacks(hideControls);normalVideo();body.setVisibility(View.VISIBLE);round(surface,20);configureWindow(false);controls.setVisibility(View.VISIBLE);channelTitle.setVisibility(View.VISIBLE);playingLogo.setVisibility(View.VISIBLE);controlsVisible=true;fullscreen.setText("⛶ ملء الشاشة");videoPane.post(()->{if(beforeFull!=null&&beforeFull.isAttachedToWindow())beforeFull.requestFocus();else fullscreen.requestFocus();});}texture.post(this::fitVideo);}
 private void fitVideo(){int w=texture.getWidth(),h=texture.getHeight();if(w<=0||h<=0||videoWidth<=0||videoHeight<=0)return;float scale=Math.min(w/(float)videoWidth,h/(float)videoHeight);Matrix m=new Matrix();m.setScale(videoWidth*scale/w,videoHeight*scale/h,w/2f,h/2f);texture.setTransform(m);}
 private void showControls(){controlsVisible=true;controls.setVisibility(View.VISIBLE);channelTitle.setVisibility(View.VISIBLE);playingLogo.setVisibility(View.VISIBLE);ui.removeCallbacks(hideControls);if(full&&engine!=null&&engine.player.isPlaying())ui.postDelayed(hideControls,4000);}
 private void selectSection(int n){section=n;repository.section(n);favoritesOnly=false;favorites.setSelected(false);paint(favorites);position=0;resetSelection=true;revealTab(n);load(false);}
 private void revealTab(int n){tabScroll.post(()->{View t=tabs[n];int left=t.getLeft()-px(10),right=t.getRight()+px(10);if(left<tabScroll.getScrollX())tabScroll.smoothScrollTo(left,0);else if(right>tabScroll.getScrollX()+tabScroll.getWidth())tabScroll.smoothScrollTo(right-tabScroll.getWidth(),0);});}
 void load(boolean force){if(closing)return;int ticket=++loadTicket;int chosen=section;if(request!=null)request.cancel(true);LiveTvRepository.Snapshot saved=snapshots.get(section);if(saved!=null){snapshot=saved;render();}else{channelList.clearChoices();adapter.items.clear();adapter.notifyDataSetChanged();empty.setVisibility(View.VISIBLE);empty.setText("جارٍ تحميل القنوات وبيانات المصدر…");}footer.setText("↻ جارٍ تحديث القوائم… • تبقى آخر نسخة ناجحة محفوظة");request=repository.load(chosen,force,result->{if(closing||ticket!=loadTicket)return;snapshot=result;snapshots.put(chosen,result);render();});}
 private void render(){if(snapshot==null)return;String selectedId=resetSelection||adapter.items.isEmpty()?"":adapter.getItem(Math.min(position,adapter.getCount()-1)).key();resetSelection=false;List<LiveTvData.Channel> items=favoritesOnly?repository.savedFavorites():snapshot.channels;channelList.clearChoices();adapter.items.clear();adapter.items.addAll(items);adapter.notifyDataSetChanged();int target=0;for(int i=0;i<items.size();i++)if(items.get(i).key().equals(selectedId))target=i;position=Math.min(target,Math.max(0,items.size()-1));if(!items.isEmpty())channelList.setSelection(position);
  empty.setVisibility(items.isEmpty()?View.VISIBLE:View.GONE);empty.setText(favoritesOnly?"لم تُضف قنوات إلى المفضلة بعد":snapshot.message.isEmpty()?"لا توجد قنوات متاحة حاليًا":snapshot.message);
  for(int i=0;i<tabs.length;i++){tabs[i].setSelected(i==section);paint(tabs[i]);}
  footer.setText((snapshot.cached||snapshot.failed?"نسخة محفوظة • البث يحتاج اتصالًا • ":"")+"آخر تحديث: "+(snapshot.updated>0?LiveTvData.time(snapshot.updated):"غير متاح")+" — توقيت السعودية • "+items.size()+" قناة • iptv-org");
 }
 private void focusList(){if(adapter.getCount()>0){channelList.requestFocus();channelList.setSelection(Math.min(position,adapter.getCount()-1));}else play.requestFocus();}
 void play(LiveTvData.Channel c,int index){if(c==null)return;playing=c;channelTitle.setText(c.name);LiveTvImages.load(host,playingLogo,c.logo,160);updateFavorite();engine.play(c,index);showControls();loadGuide();}
 private void updateFavorite(){favorite.setText(playing!=null&&repository.favorite(playing)?"★ إزالة المفضلة":"☆ المفضلة");adapter.notifyDataSetChanged();}
