 @Override public boolean dispatchKeyEvent(KeyEvent e){int k=e.getKeyCode();if(k==KeyEvent.KEYCODE_BACK){if(e.getAction()==KeyEvent.ACTION_UP){if(panel!=null)closePanel();else if(full)setFull(false);else dismiss();}return true;}if(closing)return true;
  if(k==KeyEvent.KEYCODE_MEDIA_PLAY_PAUSE||k==KeyEvent.KEYCODE_MEDIA_PLAY||k==KeyEvent.KEYCODE_MEDIA_PAUSE){if(e.getAction()==KeyEvent.ACTION_DOWN){if(k==KeyEvent.KEYCODE_MEDIA_PLAY)engine.player.play();else if(k==KeyEvent.KEYCODE_MEDIA_PAUSE)engine.player.pause();else engine.toggle();showControls();}return true;}
  if(panel!=null)return super.dispatchKeyEvent(e);
  boolean direction=k==KeyEvent.KEYCODE_DPAD_LEFT||k==KeyEvent.KEYCODE_DPAD_RIGHT||k==KeyEvent.KEYCODE_DPAD_UP||k==KeyEvent.KEYCODE_DPAD_DOWN;View focus=getCurrentFocus();
  if(full){if(e.getAction()==KeyEvent.ACTION_DOWN&&(direction||k==KeyEvent.KEYCODE_DPAD_CENTER)){if(!controlsVisible||focus==texture){showControls();play.requestFocus();return true;}showControls();if(direction){View[] actions={play,favorite,source,fullscreen};int index=index(actions,focus);actions[Math.floorMod(index+(k==KeyEvent.KEYCODE_DPAD_LEFT?-1:1),actions.length)].requestFocus();return true;}}return super.dispatchKeyEvent(e);}
  if(direction){if(e.getAction()==KeyEvent.ACTION_UP)return true;int tab=index(tabs,focus);if(tab>=0){if(k==KeyEvent.KEYCODE_DPAD_LEFT||k==KeyEvent.KEYCODE_DPAD_RIGHT){int next=Math.floorMod(tab+(k==KeyEvent.KEYCODE_DPAD_LEFT?1:-1),tabs.length);tabs[next].requestFocus();revealTab(next);}else if(k==KeyEvent.KEYCODE_DPAD_UP)close.requestFocus();else focusList();return true;}
   if(focus==close){tabs[section].requestFocus();revealTab(section);return true;}
   if(focus==channelList){int selected=channelList.getSelectedItemPosition();if(k==KeyEvent.KEYCODE_DPAD_RIGHT){play.requestFocus();return true;}if(k==KeyEvent.KEYCODE_DPAD_LEFT){tabs[section].requestFocus();revealTab(section);return true;}if(k==KeyEvent.KEYCODE_DPAD_UP&&selected<=0){tabs[section].requestFocus();return true;}if(k==KeyEvent.KEYCODE_DPAD_DOWN&&selected>=adapter.getCount()-1){search.requestFocus();return true;}return super.dispatchKeyEvent(e);}
   View[] action={search,favorites,last,refresh,epg,settings};int a=index(action,focus);if(a>=0){if(k==KeyEvent.KEYCODE_DPAD_UP)focusList();else action[Math.floorMod(a+(k==KeyEvent.KEYCODE_DPAD_LEFT?-1:1),action.length)].requestFocus();return true;}
   View[] transport={play,favorite,source,fullscreen};int t=index(transport,focus);if(t>=0||focus==texture){if(k==KeyEvent.KEYCODE_DPAD_UP){tabs[section].requestFocus();revealTab(section);}else if(k==KeyEvent.KEYCODE_DPAD_DOWN)epg.requestFocus();else if(k==KeyEvent.KEYCODE_DPAD_LEFT&&t<=0)focusList();else transport[Math.floorMod(t+(k==KeyEvent.KEYCODE_DPAD_LEFT?-1:1),transport.length)].requestFocus();return true;}
   tabs[section].requestFocus();return true;
  }
  return super.dispatchKeyEvent(e);
 }
 private int index(View[] a,View v){for(int i=0;i<a.length;i++)if(a[i]==v)return i;return -1;}
 @Override public void dismiss(){if(closing)return;if(panel!=null){closePanel();}closing=true;ui.removeCallbacksAndMessages(null);engine.release();surface.animate().cancel();surface.animate().alpha(0).scaleX(.9f).scaleY(.9f).setDuration(220).withEndAction(()->super.dismiss()).start();}
